import React, { useState } from "react";
import "./Bank.css";

function Bank() {
  const [balance, setBalance] = useState();

  const addBalanceChange = (e) => {
    console.log(e.type.value);
  };

  return (
    <div>
      <div className="cont-bank">
        <label>Enter Amount(Rs.): </label>
        <input type="number" onChange={addBalanceChange} />
        <button>Add Balance</button>
      </div>
      <div>
        <label>Current Balance: </label>
        <label>{balance}</label>
      </div>
    </div>
  );
}

export default Bank;
